      --radius-lg: 24px;
      --radius-md: 16px;
      --radius-sm: 12px;
      --focus: 0 0 0 3px #c7d2fe;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, #eef2ff 0, transparent 34%),
        linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
      color: var(--text);
      min-height: 100vh;
    }

    a {
      color: inherit;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      transform: translateY(-140%);
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 999px;
      padding: 0.75rem 1rem;
      z-index: 20;
      transition: transform 0.2s ease;
      box-shadow: var(--shadow);
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: none;
      box-shadow: var(--focus), var(--shadow);
    }

    main {
      width: min(100%, 1120px);
      margin: 0 auto;
      padding: 2rem 1rem 3rem;
    }

    .preview-shell {
      display: grid;
      grid-template-columns: minmax(0, 1.25fr) minmax(280px, 0.75fr);
      gap: 1.5rem;
      align-items: start;
    }

    .hero,
    .side-panel {
      background: color-mix(in srgb, var(--surface) 92%, white);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
    }

    .hero {
      padding: 1rem;
    }

    .hero-media {
      aspect-ratio: 4 / 3;
      border-radius: calc(var(--radius-lg) - 8px);
      overflow: hidden;
      background: linear-gradient(135deg, #dbeafe 0%, #e0e7ff 50%, #ede9fe 100%);
      border: 1px solid #dbe4f2;
      display: grid;
      place-items: center;
      position: relative;
    }

    .hero-media::after {
      content: "";
      position: absolute;
      inset: auto -10% -18% -10%;
      height: 42%;
      background: linear-gradient(180deg, transparent, rgba(255, 255, 255, 0.4));
      transform: rotate(-3deg);
    }

    .image-card {
      width: min(88%, 520px);
      aspect-ratio: 1 / 1;
      border-radius: 30px;
      background: linear-gradient(145deg, #ffffff, #dbeafe 55%, #c4b5fd 100%);
      box-shadow: 0 30px 70px rgba(59, 130, 246, 0.22);
      position: relative;
      overflow: hidden;
    }

    .image-card::before,
    .image-card::after {
      content: "";
      position: absolute;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.55);
    }

    .image-card::before {
      width: 46%;
      height: 46%;
      top: 10%;
      left: 10%;
    }

    .image-card::after {
      width: 28%;
      height: 28%;
      right: 12%;
      bottom: 12%;
    }

    .hero-copy {
      padding: 1rem 0.25rem 0.25rem;
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(1.85rem, 3vw, 3rem);
      line-height: 1.1;
      letter-spacing: -0.03em;
    }

    .lede {
      margin: 0;
      max-width: 62ch;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.65;
    }

    .action-row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      align-items: center;
      margin-top: 1.25rem;
    }

    .button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 0.9rem 1.2rem;
      font: inherit;
      font-weight: 600;
      cursor: pointer;
      transition: transform 0.15s ease, background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button:focus-visible {
      outline: none;
      box-shadow: var(--focus);
    }

    .button.primary {
      background: var(--accent);
      color: #fff;
      box-shadow: 0 14px 30px rgba(79, 70, 229, 0.28);
    }

    .button.primary:hover {
      background: var(--accent-strong);
    }

    .button.secondary {
      background: var(--surface-2);
      color: var(--text);
      border: 1px solid var(--border);
    }

    .button.destructive {
      background: var(--danger);
      color: #fff;
      box-shadow: 0 14px 30px rgba(194, 65, 95, 0.24);
    }

    .button.destructive:hover {
      background: var(--danger-strong);
    }

    .side-panel {
      padding: 1.25rem;
    }

    .meta {
      display: grid;
      gap: 1rem;
    }

    .meta-card {
      padding: 1rem;
      border-radius: var(--radius-md);
      background: var(--surface-2);
      border: 1px solid var(--border);
    }

    .meta-label {
      display: block;
      color: var(--muted);
      font-size: 0.85rem;
      letter-spacing: 0.02em;
      text-transform: uppercase;
      margin-bottom: 0.35rem;
    }

    .meta-value {
      display: block;
      font-weight: 600;
      line-height: 1.45;
      overflow-wrap: anywhere;
    }

    .status {
      min-height: 1.5rem;
      font-size: 0.95rem;
      color: var(--muted);
      margin-top: 1rem;
    }

    .status[data-state="deleted"] {
      color: var(--danger-strong);
      font-weight: 600;
    }

    dialog {
      width: min(92vw, 460px);
      border: 1px solid var(--border);
      border-radius: 24px;
      padding: 0;
      box-shadow: 0 32px 90px rgba(15, 23, 42, 0.25);
      color: var(--text);
      background: var(--surface);
    }

    dialog::backdrop {
      background: rgba(15, 23, 42, 0.5);
      backdrop-filter: blur(4px);
    }

    .dialog-body {
      padding: 1.25rem;
    }

    .dialog-header {
      display: flex;
      align-items: flex-start;
      gap: 0.9rem;
      margin-bottom: 1rem;
    }

    .dialog-icon {
      width: 2.75rem;
      height: 2.75rem;
      border-radius: 50%;
      flex: 0 0 auto;
      display: grid;
      place-items: center;
      color: #fff;
      background: linear-gradient(135deg, #ef4444, #b91c1c);
    }

    .dialog-title {
      margin: 0;
      font-size: 1.2rem;
      line-height: 1.25;
    }

    .dialog-copy {
      margin: 0;
      color: var(--muted);
      line-height: 1.65;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      flex-wrap: wrap;
      gap: 0.75rem;
      margin-top: 1.5rem;
    }

    .subtle-note {
      margin: 0.9rem 0 0;
      font-size: 0.92rem;
      color: var(--muted);
    }

    .is-hidden {
      display: none;
    }

    @media (max-width: 860px) {
      .preview-shell {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 640px) {
      main {
        padding-inline: 0.75rem;
      }

      .hero,
      .side-panel {
        border-radius: 20px;
      }

      .dialog-actions {
        justify-content: stretch;
      }

      .dialog-actions .button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-2: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --border: ButtonBorder;
        --accent: ButtonText;
        --accent-strong: ButtonText;
        --danger: ButtonText;
        --danger-strong: ButtonText;
        --shadow: none;
      }

      .button,
      .hero,
      .side-panel,
      dialog {
        forced-color-adjust: auto;
      }

      .button.primary,
      .button.destructive {
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonBorder;
      }

      .button.secondary {
        background: ButtonFace;
        color: ButtonText;
      }

      .hero-media,
      .image-card,
      .dialog-icon {
        border: 1px solid ButtonBorder;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <div class="preview-shell">
      <section class="hero" aria-labelledby="page-title">
        <div class="hero-media" aria-hidden="true">
          <div class="image-card"></div>
        </div>
        <div class="hero-copy">
          <h1 id="page-title">Image Preview</h1>
          <p class="lede">
            Review the image before removing it from your library. The delete action is protected by a confirmation dialog so accidental taps do not remove the file.
          </p>
          <div class="action-row">
            <button type="button" class="button destructive trigger" id="delete-trigger" aria-haspopup="dialog">
              Delete image
            </button>
            <button type="button" class="button secondary" id="save-copy">
              Save a copy
            </button>
          </div>
          <p class="subtle-note">File: sunset-bridge-edit.jpg</p>
        </div>
      </section>

      <aside class="side-panel" aria-label="Image details">
        <div class="meta">
          <div class="meta-card">
            <span class="meta-label">Library</span>
            <span class="meta-value">Travel shoots</span>
          </div>
          <div class="meta-card">
            <span class="meta-label">Uploaded</span>
            <span class="meta-value">May 4, 2026</span>
          </div>
          <div class="meta-card">
            <span class="meta-label">Size</span>
            <span class="meta-value">6.8 MB · 4032 x 3024 px</span>
          </div>
        </div>
        <div id="status" class="status" aria-live="polite"></div>
      </aside>
    </div>
  </main>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <div class="dialog-body">
      <div class="dialog-header">
        <div class="dialog-icon" aria-hidden="true">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <path d="M12 8v5" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/>
            <path d="M12 17.25h.01" stroke="currentColor" stroke-width="3.2" stroke-linecap="round"/>
            <path d="M10.3 4.4 2.9 18a2 2 0 0 0 1.75 3h14.7a2 2 0 0 0 1.75-3l-7.4-13.6a2 2 0 0 0-3.4 0Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/>
          </svg>
        </div>
        <div>
          <h2 class="dialog-title" id="dialog-title">Delete this image?</h2>
          <p class="dialog-copy" id="dialog-description">
            This will remove the image from your library. You can&apos;t undo this action after it&apos;s deleted.
          </p>
        </div>
      </div>

      <div class="dialog-actions">
        <button type="button" class="button secondary" id="cancel-delete">Cancel</button>
        <button type="button" class="button destructive" id="confirm-delete">Delete permanently</button>
      </div>
    </div>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const deleteTrigger = document.getElementById('delete-trigger');
    const cancelDelete = document.getElementById('cancel-delete');
    const confirmDelete = document.getElementById('confirm-delete');
    const status = document.getElementById('status');
    const saveCopy = document.getElementById('save-copy');
    let lastTrigger = null;

    deleteTrigger.addEventListener('click', () => {
      lastTrigger = document.activeElement;
      dialog.showModal();
      cancelDelete.focus();
    });

    cancelDelete.addEventListener('click', () => {
      dialog.close('cancel');
    });

    confirmDelete.addEventListener('click', () => {
      dialog.close('delete');
      status.dataset.state = 'deleted';
      status.textContent = 'Image deleted from your library.';
      saveCopy.disabled = true;
      deleteTrigger.disabled = true;
      deleteTrigger.textContent = 'Image deleted';
    });

    dialog.addEventListener('close', () => {
      if (dialog.returnValue !== 'delete') {
        status.removeAttribute('data-state');
      }
      if (lastTrigger instanceof HTMLElement) {
        lastTrigger.focus();
      } else {
        deleteTrigger.focus();
      }
    });

    dialog.addEventListener('click', (event) => {
      const rect = dialog.getBoundingClientRect();
      const clickedInDialog =
        event.clientX >= rect.left &&
        event.clientX <= rect.right &&
        event.clientY >= rect.top &&
        event.clientY <= rect.bottom;

      if (!clickedInDialog) {
        dialog.close('cancel');
      }
    });

    saveCopy.addEventListener('click', () => {
      status.removeAttribute('data-state');
      status.textContent = 'A local copy was saved to your downloads folder.';
    });
  </script>
